-- TAKTIK local database: schema version 1, the baseline of the bot's objects.
-- Generated by scripts/build_schema_baseline.py from a base at the 1.9.8 schema.
-- Do not edit: a schema change is a new numbered migration.
-- The desktop app's own tables, views and triggers are not here: the app keeps them.

-- tables
CREATE TABLE filtered_profiles (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      profile_id INTEGER NOT NULL,
      account_id INTEGER NOT NULL,
      username TEXT NOT NULL,
      filtered_at TEXT DEFAULT (datetime('now')),
      reason TEXT,
      source_type TEXT DEFAULT 'GENERAL',
      source_name TEXT DEFAULT 'unknown',
      session_id INTEGER,
      sync_id TEXT,
      UNIQUE(platform, profile_id, account_id)
    );

CREATE TABLE dm_threads (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      account_id INTEGER NOT NULL,
      partner_username TEXT NOT NULL,
      partner_profile_id INTEGER,
      external_thread_id TEXT,
      is_group INTEGER DEFAULT 0,
      can_reply INTEGER DEFAULT 1,
      last_message_text TEXT,
      last_message_at TEXT,
      last_message_is_ours INTEGER DEFAULT 0,
      unread_count INTEGER DEFAULT 0,
      message_count INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      sync_id TEXT,
      UNIQUE(platform, account_id, partner_username)
    );

CREATE TABLE dm_messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      thread_sync_id TEXT NOT NULL,
      account_id INTEGER,
      partner_username TEXT,
      direction TEXT NOT NULL,
      msg_type TEXT DEFAULT 'text',
      text TEXT,
      content_hash TEXT NOT NULL,
      seq INTEGER DEFAULT 0,
      sent_at TEXT DEFAULT (datetime('now')),
      displayed_at TEXT,
      ai_model TEXT,
      ai_cost_usd REAL,
      sync_id TEXT, reaction TEXT,
      UNIQUE(platform, thread_sync_id, direction, content_hash)
    );

CREATE TABLE notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      account_id INTEGER NOT NULL,
      actor_username TEXT,
      actor_profile_id INTEGER,
      type TEXT,
      raw_category TEXT,
      label TEXT,
      body TEXT,
      relative_time TEXT,
      has_action INTEGER DEFAULT 0,
      attributed INTEGER DEFAULT 0,
      attribution_type TEXT,
      attribution_at TEXT,
      content_hash TEXT NOT NULL,
      first_seen_at TEXT DEFAULT (datetime('now')),
      last_seen_at TEXT DEFAULT (datetime('now')),
      sync_id TEXT,
      UNIQUE(platform, account_id, content_hash)
    );

CREATE TABLE account_restriction_signals (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      account_username TEXT NOT NULL,
      detected_at TEXT DEFAULT (datetime('now')),
      signal TEXT NOT NULL DEFAULT 'private_first_ordering',
      source_type TEXT,
      source_name TEXT,
      source_followers INTEGER,
      streak INTEGER,
      encounter_order INTEGER,
      jump_index INTEGER,
      gestures INTEGER,
      session_id INTEGER,
      sync_id TEXT
    );

CREATE TABLE posted_comments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      account_id INTEGER,
      session_id INTEGER,
      target_username TEXT NOT NULL,
      post_author TEXT,
      post_ref TEXT,
      post_url TEXT,
      post_caption TEXT,
      post_description TEXT,
      kind TEXT NOT NULL DEFAULT 'comment',
      reply_to_username TEXT,
      reply_to_text TEXT,
      comment_text TEXT NOT NULL,
      source TEXT NOT NULL DEFAULT 'ai',
      ai_model TEXT,
      ai_cost_usd REAL,
      ai_reasoning TEXT,
      language TEXT,
      posted_at TEXT DEFAULT (datetime('now')),
      created_at TEXT DEFAULT (datetime('now')),
      sync_id TEXT
    );

CREATE TABLE device_identity (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        device_id TEXT NOT NULL,
        created_at TEXT DEFAULT (datetime('now'))
      );

CREATE TABLE interactions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT NOT NULL DEFAULT 'instagram',
        legacy_id INTEGER,
        session_id INTEGER,
        account_id INTEGER,
        profile_id INTEGER,
        interaction_type TEXT NOT NULL,
        success INTEGER DEFAULT 1,
        content TEXT,
        video_id TEXT,
        interaction_time TEXT DEFAULT (datetime('now')),
        created_at TEXT DEFAULT (datetime('now')),
        sync_id TEXT,
        account_username TEXT,
        target_username TEXT,
        origin_device_id TEXT,
        session_sync_id TEXT, source TEXT DEFAULT 'bot',
        UNIQUE(platform, legacy_id)
      );

CREATE TABLE daily_stats_unified (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT NOT NULL DEFAULT 'instagram',
        account_id INTEGER NOT NULL,
        date TEXT NOT NULL,
        total_likes INTEGER DEFAULT 0,
        total_follows INTEGER DEFAULT 0,
        total_unfollows INTEGER DEFAULT 0,
        total_comments INTEGER DEFAULT 0,
        total_profile_visits INTEGER DEFAULT 0,
        total_story_views INTEGER DEFAULT 0,
        total_story_likes INTEGER DEFAULT 0,
        total_favorites INTEGER DEFAULT 0,
        total_shares INTEGER DEFAULT 0,
        total_posts_watched INTEGER DEFAULT 0,
        total_sessions INTEGER DEFAULT 0,
        completed_sessions INTEGER DEFAULT 0,
        failed_sessions INTEGER DEFAULT 0,
        total_duration_seconds INTEGER DEFAULT 0,
        synced_to_api INTEGER DEFAULT 0,
        synced_at TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now')),
        UNIQUE(platform, account_id, date)
      );

CREATE TABLE sessions_unified (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT NOT NULL DEFAULT 'instagram',
        legacy_session_id INTEGER,
        account_id INTEGER,
        session_name TEXT,
        target_type TEXT,
        workflow_type TEXT,
        target TEXT,
        start_time TEXT,
        end_time TEXT,
        duration_seconds INTEGER,
        config_used TEXT,
        status TEXT,
        error_message TEXT,
        synced_to_api INTEGER DEFAULT 0,
        ai_total_cost_usd REAL DEFAULT 0,
        ai_profiles_analyzed INTEGER DEFAULT 0,
        ai_posts_analyzed INTEGER DEFAULT 0,
        ai_comments_generated INTEGER DEFAULT 0,
        stats_total_interactions INTEGER DEFAULT 0,
        stats_likes INTEGER DEFAULT 0,
        stats_follows INTEGER DEFAULT 0,
        stats_unfollows INTEGER DEFAULT 0,
        stats_comments INTEGER DEFAULT 0,
        stats_story_views INTEGER DEFAULT 0,
        stats_story_likes INTEGER DEFAULT 0,
        stats_profile_visits INTEGER DEFAULT 0,
        profiles_visited INTEGER DEFAULT 0,
        posts_watched INTEGER DEFAULT 0,
        likes INTEGER DEFAULT 0,
        follows INTEGER DEFAULT 0,
        favorites INTEGER DEFAULT 0,
        comments INTEGER DEFAULT 0,
        shares INTEGER DEFAULT 0,
        errors INTEGER DEFAULT 0,
        videos_watched INTEGER DEFAULT 0,
        ai_cost_by_kind TEXT,
        stop_reason_code TEXT,
        stop_reason_params TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now')),
        sync_id TEXT,
        UNIQUE(platform, legacy_session_id)
      );

CREATE TABLE "scraped_profiles" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            platform TEXT NOT NULL DEFAULT 'instagram',
            scraping_id INTEGER NOT NULL,
            profile_id INTEGER NOT NULL,
            scraped_at TEXT DEFAULT (datetime('now')),
            is_enriched INTEGER DEFAULT 0,
            ai_score INTEGER,
            ai_qualified INTEGER DEFAULT 0,
            ai_analysis TEXT,
            qualification_criteria TEXT,
            scored_at TEXT,
            source_post_url TEXT,
            UNIQUE(scraping_id, profile_id)
          );

CREATE TABLE "social_graph_sync" (
        id INTEGER PRIMARY KEY AUTOINCREMENT, platform TEXT NOT NULL DEFAULT 'instagram', account_id INTEGER NOT NULL,
        username TEXT NOT NULL COLLATE NOCASE, direction TEXT NOT NULL, display_name TEXT DEFAULT '',
        is_reciprocal INTEGER DEFAULT NULL, followed_by_bot INTEGER DEFAULT 0, unfollowed_at TEXT DEFAULT NULL,
        first_seen_at TEXT DEFAULT (datetime('now')), last_seen_at TEXT DEFAULT (datetime('now')),
        source TEXT DEFAULT 'sync', UNIQUE(platform, account_id, username, direction));

CREATE TABLE "profile_stats_history" (
        id INTEGER PRIMARY KEY AUTOINCREMENT, profile_id INTEGER NOT NULL, followers_count INTEGER NOT NULL,
        following_count INTEGER NOT NULL, posts_count INTEGER NOT NULL, engagement_rate REAL, is_verified INTEGER,
        biography TEXT, external_url TEXT, profile_pic_url TEXT, recorded_at TEXT DEFAULT (datetime('now')),
        is_business INTEGER DEFAULT 0, category TEXT, sync_id TEXT, username TEXT);

CREATE TABLE accounts (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          platform TEXT NOT NULL DEFAULT 'instagram',
          legacy_account_id INTEGER,
          username TEXT NOT NULL,
          is_bot INTEGER DEFAULT 1,
          user_id INTEGER,
          license_id INTEGER,
          display_name TEXT,
          qualification_prompt TEXT,
          bio TEXT,
          niche TEXT,
          product_service TEXT,
          objective TEXT,
          target_audience TEXT,
          tone_personality TEXT,
          preferred_language TEXT,
          website TEXT,
          unique_selling_point TEXT,
          custom_context TEXT,
          created_at TEXT DEFAULT (datetime('now')),
          updated_at TEXT DEFAULT (datetime('now')),
          sync_id TEXT, warmup_intensity TEXT, warmup_preset_id INTEGER,
          UNIQUE(platform, legacy_account_id)
        );

CREATE TABLE social_profiles (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          platform TEXT NOT NULL DEFAULT 'instagram',
          legacy_profile_id INTEGER,
          username TEXT NOT NULL,
          display_name TEXT DEFAULT '',
          biography TEXT,
          followers_count INTEGER DEFAULT 0,
          following_count INTEGER DEFAULT 0,
          posts_count INTEGER DEFAULT 0,
          likes_count INTEGER DEFAULT 0,
          is_private INTEGER DEFAULT 0,
          is_verified INTEGER DEFAULT 0,
          is_business INTEGER DEFAULT 0,
          business_category TEXT,
          website TEXT,
          profile_pic_path TEXT,
          ai_screenshot_path TEXT,
          notes TEXT,
          account_based_in TEXT,
          date_joined TEXT,
          location_city TEXT,
          location_region TEXT,
          primary_language TEXT,
          created_at TEXT DEFAULT (datetime('now')),
          updated_at TEXT DEFAULT (datetime('now')),
          sync_id TEXT, unreachable_at TEXT, unreachable_count INTEGER DEFAULT 0,
          UNIQUE(platform, legacy_profile_id)
        );

CREATE TABLE "sent_dms" (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      account_id INTEGER NOT NULL,
      recipient_username TEXT NOT NULL,
      message_hash TEXT,
      sent_at TEXT DEFAULT (datetime('now')),
      success INTEGER DEFAULT 1,
      error_message TEXT,
      session_id TEXT,
      sync_id TEXT,
      platform TEXT NOT NULL DEFAULT 'instagram',
      UNIQUE(account_id, recipient_username, platform));

CREATE TABLE scraping_sessions (
            scraping_id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER,
            scraping_type TEXT NOT NULL,
            source_type TEXT NOT NULL,
            source_name TEXT NOT NULL,
            total_scraped INTEGER DEFAULT 0,
            max_profiles INTEGER DEFAULT 500,
            export_csv INTEGER DEFAULT 0,
            csv_path TEXT,
            save_to_db INTEGER DEFAULT 1,
            start_time TEXT DEFAULT (datetime('now')),
            end_time TEXT,
            duration_seconds INTEGER DEFAULT 0,
            status TEXT DEFAULT 'RUNNING',
            error_message TEXT,
            config_used TEXT,
            platform TEXT DEFAULT 'instagram',
            sync_id TEXT,
            created_at TEXT DEFAULT (datetime('now'))
        , updated_at TEXT);

CREATE TABLE processed_hashtag_posts (
