            processed_at TEXT DEFAULT (datetime('now')),
            UNIQUE(account_id, hashtag, post_author, post_caption_hash)
        );

CREATE TABLE profile_following (
            id                 INTEGER PRIMARY KEY AUTOINCREMENT,
            profile_username   TEXT NOT NULL,
            profile_id         INTEGER,
            following_username TEXT NOT NULL,
            following_id       INTEGER,
            session_id         TEXT,
            discovered_at      TEXT DEFAULT (datetime('now')), niche_category TEXT, niche TEXT, gender TEXT, classified_at TEXT,
            UNIQUE(profile_username, following_username)
        );

CREATE TABLE notification_actions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            platform TEXT NOT NULL DEFAULT 'instagram',
            account_id INTEGER NOT NULL,
            content_hash TEXT,
            actor_username TEXT,
            action TEXT NOT NULL,
            source TEXT NOT NULL DEFAULT 'manual',
            success INTEGER NOT NULL DEFAULT 1,
            created_at TEXT DEFAULT (datetime('now'))
        );

CREATE TABLE post_analysis (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            platform TEXT NOT NULL DEFAULT 'instagram',
            post_ref TEXT NOT NULL,
            post_author TEXT,
            post_caption TEXT,
            description TEXT,
            post_language TEXT,
            ai_model TEXT,
            ai_cost_usd REAL,
            hit_count INTEGER DEFAULT 0,
            analyzed_at TEXT DEFAULT (datetime('now')),
            last_used_at TEXT,
            created_at TEXT DEFAULT (datetime('now')),
            sync_id TEXT,
            UNIQUE(platform, post_ref)
        );

CREATE TABLE ai_prompt_bodies (
            hash TEXT PRIMARY KEY,
            kind TEXT NOT NULL,
            body TEXT NOT NULL,
            chars INTEGER,
            first_seen_at TEXT DEFAULT (datetime('now')),
            last_seen_at TEXT DEFAULT (datetime('now')),
            uses INTEGER NOT NULL DEFAULT 0
        );

CREATE TABLE ai_call_captures (
